8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/components/product-view/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * Apart from the one added prop described in the next paragraph, the differences from the base
14	 * file are the TypeScript annotations below, house formatting, and a small number of
15	 * optional-chaining guards that strictNullChecks requires — each flagged in place with a
16	 * `Deviation from the base file` comment.
17	 *
18	 * Per the SFCC bridge pattern in .claude/rules/overrideStyling.md, the default export stays a
19	 * faithful port with the same `forwardRef` behaviour. It carries exactly one additive optional
20	 * prop over the base file's surface — `renderHeader`, documented on `ProductViewProps` below.
21	 * It is behaviour-preserving when omitted (its default renders the same private
22	 * `ProductViewHeader` the base file renders inline), and `renderHeader` has zero occurrences in
23	 * the base package, so none of the four base modules that import ProductView — product-view-modal
24	 * (index and bundle), bonus-product-view-modal, and pages/product-detail — passes it or is
25	 * affected by it. (The runtime `propTypes` blocks are replaced by the TypeScript prop types; see
26	 * the note at the foot of the file.)
27	 */
28	
29	import React, { forwardRef, useEffect, useMemo, useRef, useState, useCallback } from 'react';
30	import { useLocation } from 'react-router-dom';
31	import { useIntl, FormattedMessage } from 'react-intl';
32	
33	import {
34	  Flex,
35	  Heading,
36	  Button,
37	  Skeleton,
38	  Box,
39	  Text,
40	  VStack,
41	  Fade,
42	  Stack,
43	  Radio,
44	  RadioGroup,
45	  useTheme,
46	} from '@salesforce/retail-react-app/app/components/shared/ui';
47	
48	// Constants
49	const DELIVERY_OPTIONS = {
50	  DELIVERY: 'delivery',
51	  PICKUP: 'pickup',
52	};
53	import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
54	import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
55	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
56	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
57	import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
58	import { useSFPayments, useExpressCheckoutEnabled } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
59	
60	// project components
61	import ImageGallery from '@salesforce/retail-react-app/app/components/image-gallery';
62	import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
63	import Link from '@salesforce/retail-react-app/app/components/link';
64	import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
65	import { Skeleton as ImageGallerySkeleton } from '@salesforce/retail-react-app/app/components/image-gallery';
66	import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive';
67	import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker';
68	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
69	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
70	import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
71	import Swatch from '@salesforce/retail-react-app/app/components/swatch-group/swatch';
72	import SwatchGroup from '@salesforce/retail-react-app/app/components/swatch-group';
73	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
74	import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
75	import SFPaymentsExpressButtons from '@salesforce/retail-react-app/app/components/sf-payments-express-buttons';
76	import { EXPRESS_BUY_NOW } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
77	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
78	import { useCleanupTemporaryBaskets } from '@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets';
79	
80	/*
81	 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
82	 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
83	 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
84	 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
85	 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
86	 *
87	 * Substituting them is a follow-up rather than part of this PR only because it also removes
88	 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
89	 * across every commit.
90	 */
91	type SfccProduct = any;
92	type SfccVariant = any;
93	type SfccCategory = any;
94	type SfccPriceData = any;
95	
96	/** One selectable value of a variation attribute, as the base hooks shape it. */
97	type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };
98	
99	/** A variation attribute (colour, size, ...) with its selectable values. */
100	type SfccVariationAttribute = {
101	  id: string;
102	  name?: string;
103	  selectedValue?: SfccVariationValue;
104	  values: SfccVariationValue[];
105	};
106	
107	/** SFCC variation attribute ID for the colour attribute. */
108	export const SFCC_COLOUR_ATTRIBUTE_ID = 'color';
109	
110	/** The per-child orderability record ProductView writes back to its parent. */
111	export type ChildProductOrderability = {
112	  showInventoryMessage?: boolean;
113	  unfulfillable?: boolean;
114	  isOutOfStock?: boolean;
115	  stockLevel?: number;
116	  productName?: string;
117	};
118	
119	export type ProductViewHeaderProps = {
120	  name?: string;
121	  currency?: string;
122	  priceData?: SfccPriceData;
123	  category?: SfccCategory[];
124	  product?: SfccProduct;
125	  isProductPartOfBundle?: boolean;
126	};
127	
128	/*
129	 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
130	 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
131	 * from the default implementation the base file supplies.
132	 */
133	type ProductViewProps = {
134	  product?: SfccProduct;
135	  category?: SfccCategory[];
136	  showFullLink?: boolean;
137	  imageSize?: 'sm' | 'md';
138	  isWishlistLoading?: boolean;
139	  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
140	  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
141	  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
142	  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
143	  isProductLoading?: boolean;
144	  isProductPartOfSet?: boolean;
145	  isProductPartOfBundle?: boolean;
146	  childOfBundleQuantity?: number;
147	  childProductOrderability?: Record<string, ChildProductOrderability>;
148	  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
149	  isBasketLoading?: boolean;
150	  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
151	  validateOrderability?: (
152	    variant: SfccVariant,
153	    product: SfccProduct,
154	    quantity: number,
155	    stockLevel: number,
156	  ) => boolean | undefined;
157	  showImageGallery?: boolean;
158	  setSelectedBundleQuantity?: (quantity: number) => void;
159	  selectedBundleParentQuantity?: number;
160	  pickupInStore?: boolean;
161	  setPickupInStore?: (checked: boolean) => void;
162	  onOpenStoreLocator?: () => void;
163	  showDeliveryOptions?: boolean;
164	  customButtons?: React.ReactElement[];
165	  promotionId?: string;
166	  maxOrderQuantity?: number | null;
167	  imageGalleryFooter?: React.ReactNode;
168	  alignItems?: string;
169	  controlledVariationValues?: Record<string, string> | null;
170	  onVariationChange?: ((attributeId: string, value: string) => void) | null;
171	  /**
172	   * The one Zimmermann addition to this component's prop surface. Replaces the header block
173	   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
174	   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
175	   * them. Defaults to rendering that same private header, so every existing caller — cart,
176	   * wishlist, bonus-product — is byte-identical unless it opts in.
177	   *
178	   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
179	   * twice with the same arguments. Keep it pure.
180	   */
181	  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
182	  /**
183	   * The second Zimmermann addition to this component's prop surface (SFCC-736/195). Renders
184	   * after the CTAs (`renderActionButtons()`), inside the same column — Figma's "Find in
185	   * Boutique" link and the Details & Care / Size & Fit / Shipping & Returns / Assistance
186	   * drawer-trigger rows. A plain node, like the existing `imageGalleryFooter` slot, not a
187	   * render-prop like `renderHeader`: this content needs none of ProductView's own render-time
188	   * data, it is driven entirely by state the caller (`product-detail/index.tsx`) already owns.
189	   * `null` by default, so every existing caller (cart, wishlist, bonus-product) is unaffected.
190	   */
191	  footerLinks?: React.ReactNode;
192	  /**
193	   * Render slot for overriding how a single variation attribute is displayed. When provided,
194	   * the returned node replaces the base SwatchGroup for that attribute. Return `undefined` (or
195	   * omit the prop) to fall through to `renderDefaultVariationAttribute` — the base SwatchGroup
196	   * rendering. The PDP uses this to inject `ZimmColourSwatchGroup` for the colour attribute;
197	   * the quick-view modal omits it and keeps the base SwatchGroup for all attributes.
198	   */
199	  renderVariationAttribute?: (attr: SfccVariationAttribute) => React.ReactNode;
200	};
201	
202	/*
203	 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
204	 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
205	 * pages/product-detail).
206	 */
207	type ProductViewRef = React.ForwardedRef<HTMLDivElement>;
208	
209	/**
210	 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
211	 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
212	 * below. A consumer names it as the `this` parameter of its ref callback —
213	 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
214	 * as written; no assertion is required at the prop site.
215	 */
216	export type ProductViewRefScope = {
217	  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
218	};
219	
220	const ProductViewHeader = ({
221	  name,
222	  currency,
223	  priceData,
224	  category,
225	  product,
226	  isProductPartOfBundle,
227	}: ProductViewHeaderProps) => {
228	  return (
229	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
230	      {category && (
231	        <Skeleton isLoaded={category} minWidth={64}>
232	          <Breadcrumb categories={category} />
233	        </Skeleton>
234	      )}
235	
236	      {/* Title */}
237	      <Skeleton isLoaded={name}>
238	        <Heading fontSize="2xl">{`${name}`}</Heading>
239	      </Skeleton>
240	
241	      {!isProductPartOfBundle && (
242	        <>
243	          <Skeleton isLoaded={priceData?.currentPrice}>
244	            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
245	          </Skeleton>
246	
247	          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
248	        </>
249	      )}
250	    </VStack>
251	  );
252	};
253	
254	const ButtonWithRegistration = withRegistration(Button);
255	
256	/**
257	 * Render a product detail view that includes name, image gallery, price,
258	 * variant selections, action buttons
259	 */
260	
261	const ProductView = forwardRef(
262	  (
263	    {
264	      product,
265	      category,
266	      showFullLink = false,
267	      imageSize = 'md',
268	      isWishlistLoading = false,
269	      addToCart,
270	      updateCart,
271	      addToWishlist,
272	      updateWishlist,
273	      isProductLoading,
274	      isProductPartOfSet = false,
275	      isProductPartOfBundle = false,
276	      childOfBundleQuantity = 0,
277	      childProductOrderability,
278	      setChildProductOrderability,
279	      isBasketLoading = false,
280	      onVariantSelected = () => {},
281	      validateOrderability = (variant, product, quantity, stockLevel) => {
282	        if (isProductLoading) return false;
283	
284	        // If product has variations, a variant must be selected
285	        if (product?.variationAttributes?.length > 0 && !variant) {
286	          return false;
287	        }
288	
289	        // Check if product (either variant or standard) is orderable and if quantity is valid
290	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
291	      },
292	      showImageGallery = true,
293	      setSelectedBundleQuantity = () => {},
294	      selectedBundleParentQuantity = 1,
295	      pickupInStore = false,
296	      setPickupInStore = () => {},
297	      onOpenStoreLocator = () => {},
298	      showDeliveryOptions = true,
299	      customButtons = [],
300	      maxOrderQuantity = null,
301	      imageGalleryFooter = null,
302	      controlledVariationValues = null,
303	      onVariationChange = null,
304	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
305	      footerLinks = null,
306	      renderVariationAttribute,
307	    }: ProductViewProps,
308	    ref: ProductViewRef,
309	  ) => {
310	    const { currency: activeCurrency } = useCurrency();
311	    const showToast = useToast();
312	    const intl = useIntl();
313	    const location = useLocation();
314	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
315	    const {
316	      isOpen: isAddToCartModalOpen,
317	      onOpen: onAddToCartModalOpen,
318	      onClose: onAddToCartModalClose,
319	    } = useAddToCartModalContext();
320	
321	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
322	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
323	
324	    const theme = useTheme();
325	    const { confirmingBasket } = useSFPayments();
326	    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
327	    const {
328	      showLoading,
329	      showInventoryMessage,
330	      inventoryMessage,
331	      quantity,
332	      minOrderQuantity,
333	      setQuantity,
334	      variant,
335	      variationParams,
336	      variationAttributes,
337	      stockLevel,
338	      stepQuantity,
339	      isOutOfStock,
340	      unfulfillable,
341	      isSelectedStoreOutOfStock,
342	      selectedStore,
343	    } = useDerivedProduct(
344	      product,
345	      isProductPartOfSet,
346	      isProductPartOfBundle,
347	      pickupInStore,
348	      controlledVariationValues,
349	      onVariationChange,
350	    );
351	    const priceData = useMemo(() => {
352	      return getPriceData(product, { quantity });
353	    }, [product, quantity]);
354	    const canAddToWishlist = !isProductLoading;
355	    const isProductASet = product?.type?.set;
356	    const isProductABundle = product?.type?.bundle;
357	    const errorContainerRef = useRef<HTMLDivElement | null>(null);
358	    const [pickupEnabled, setPickupEnabled] = useState(false);
359	    const storeName = selectedStore?.name;
360	    const inventoryId = selectedStore?.inventoryId;
361	    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();
362	
363	    const { disableButton, customInventoryMessage } = useMemo(() => {
364	      let shouldDisableButton = showInventoryMessage;
365	      let currentInventoryMsg = '';
366	      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
367	        // if any of the children are not orderable, it will disable the add to cart button
368	        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
369	          return childProductOrderability[key].showInventoryMessage;
370	        });
371	        shouldDisableButton = !!unavailableChildProductKey;
372	        if (unavailableChildProductKey) {
373	          const unavailableChildProduct = childProductOrderability[unavailableChildProductKey];
374	          if (unavailableChildProduct.unfulfillable) {
375	            currentInventoryMsg = intl.formatMessage(
376	              {
377	                defaultMessage: 'Only {stockLevel} left for {productName}!',
378	                id: 'use_product.message.inventory_remaining_for_product',
379	              },
380	              {
381	                stockLevel: unavailableChildProduct.stockLevel,
382	                productName: unavailableChildProduct.productName,
383	              },
384	            );
385	          }
386	          if (unavailableChildProduct.isOutOfStock) {
387	            currentInventoryMsg = intl.formatMessage(
388	              {
389	                defaultMessage: 'Out of stock for {productName}',
390	                id: 'use_product.message.out_of_stock_for_product',
391	              },
392	              { productName: unavailableChildProduct.productName },
393	            );
394	          }
395	        }
396	      }
397	      return { disableButton: shouldDisableButton, customInventoryMessage: currentInventoryMsg };
398	    }, [showInventoryMessage, childProductOrderability]);
399	
400	    const validateAndShowError = (opts: { scrollErrorIntoView?: boolean } = {}) => {
401	      const { scrollErrorIntoView = true } = opts;
402	      // Validate that all attributes are selected before proceeding.
403	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
404	      const showError = !isProductASet && !isProductABundle && !hasValidSelection;
405	      const scrollToError = showError && scrollErrorIntoView;
406	
407	      toggleShowOptionsMessage(showError);
408	
409	      if (scrollToError) {
410	        // Deviation from the base file: `?.`. The base dereferences `current` unguarded here
411	        // while guarding it in `prepareBasket` below; the two only differ if the error
412	        // container has not mounted, where the base throws.
413	        errorContainerRef.current?.scrollIntoView({
414	          behavior: 'smooth',
415	          block: 'center',
416	        });
417	      }
418	
419	      return hasValidSelection;
420	    };
421	    const cleanupTemporaryBaskets = useCleanupTemporaryBaskets();
422	
423	    // prepareBasket is used to prepare the basket for express payments
424	    // useCallback recreates prepareBasket primarily when product or quantity change, along with variant, stockLevel, and product type flags (isProductASet, isProductABundle)
425	    const prepareBasket = useCallback(async () => {
426	      // Validate that all attributes are selected before proceeding
427	      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
428	      let errorMessage = '';
429	
430	      if (!hasValidSelection && !isProductASet && !isProductABundle) {
431	        toggleShowOptionsMessage(true);
432	        if (errorContainerRef.current) {
433	          errorContainerRef.current.scrollIntoView({
434	            behavior: 'smooth',
435	            block: 'center',
436	          });
437	        }
438	        errorMessage = intl.formatMessage({
439	          defaultMessage: 'Please select all product options before proceeding with Express Payments',
440	          id: 'product_view.prepareBasket',
441	        });
442	
443	        const error: Error & { isValidationError?: boolean } = new Error(errorMessage);
444	        error.isValidationError = true;
445	        throw error;
446	      }
447	
448	      // Clean up temporary baskets before creating a new one
449	      await cleanupTemporaryBaskets();
450	
451	      // Create a new temporary basket
452	      const newBasket = await createBasket({
453	        parameters: {
454	          temporary: true,
455	        },
456	        body: {},
457	      });
458	
459	      const selectedProduct = variant || product;
460	      // Use variant's productId if variant is selected, otherwise use product's id
461	      const productIdToUse = selectedProduct?.productId || selectedProduct?.id;
462	
463	      if (!productIdToUse) {
464	        errorMessage = intl.formatMessage({
465	          defaultMessage: 'Unable to determine product ID for basket',
466	          id: 'product_view.prepareBasket',
467	        });
468	        throw new Error(errorMessage);
469	      }
470	      // Add the product to the temporary basket
471	      const basketWithItem = await addItemToBasket({
472	        // SDK param widening — `newBasket` is the basket just created above.
473	        parameters: { basketId: newBasket.basketId as string },
474	        body: [
475	          {
476	            productId: productIdToUse,
477	            quantity: quantity,
478	          },
479	        ],
480	      });
481	
482	      return basketWithItem;
483	    }, [variant, product, quantity, stockLevel, isProductASet, isProductABundle]);
484	
485	    const renderActionButtons = () => {
486	      const buttons = [];
487	      const buttonText = {
488	        update: intl.formatMessage({
489	          defaultMessage: 'Update',
490	          id: 'product_view.button.update',
491	        }),
492	        addToCart: intl.formatMessage({
493	          defaultMessage: 'Add to Cart',
494	          id: 'product_view.button.add_to_cart',
495	        }),
496	        addSetToCart: intl.formatMessage({
497	          defaultMessage: 'Add Set to Cart',
498	          id: 'product_view.button.add_set_to_cart',
499	        }),
500	        addBundleToCart: intl.formatMessage({
501	          defaultMessage: 'Add Bundle to Cart',
502	          id: 'product_view.button.add_bundle_to_cart',
503	        }),
504	        addToWishlist: intl.formatMessage({
505	          defaultMessage: 'Add to Wishlist',
506	          id: 'product_view.button.add_to_wishlist',
507	        }),
508	        addSetToWishlist: intl.formatMessage({
509	          defaultMessage: 'Add Set to Wishlist',
510	          id: 'product_view.button.add_set_to_wishlist',
511	        }),
512	        addBundleToWishlist: intl.formatMessage({
513	          defaultMessage: 'Add Bundle to Wishlist',
514	          id: 'product_view.button.add_bundle_to_wishlist',
515	        }),
516	      };
517	
518	      const showError = () => {
519	        showToast({
520	          title: intl.formatMessage(API_ERROR_MESSAGE),
521	          status: 'error',
522	        });
523	      };
524	
525	      const handleCartItem = async () => {
526	        const hasValidSelection = validateAndShowError();
527	
528	        if (!hasValidSelection) {
529	          return null;
530	        }
531	
532	        if (!addToCart && !updateCart) return null;
533	        if (updateCart) {
534	          await updateCart(variant || product, quantity);
535	          return;
536	        }
537	        try {
538	          // Guarded above: `!addToCart && !updateCart` returns early, and the `updateCart`
539	          // branch returns, so `addToCart` is defined here. TypeScript cannot narrow across
540	          // those two statements.
541	          const itemsAdded = await addToCart!([{ product, variant, quantity }]);
542	          // Open modal only when `addToCart` returns some data
543	          // It's possible that the item has been added to cart, but we don't want to open the modal.
544	          // See wishlist_primary_action for example.
545	          if (itemsAdded) {
546	            onAddToCartModalOpen({
547	              product,
548	              itemsAdded,
549	              selectedQuantity: quantity,
550	            });
551	          }
552	        } catch (e) {
553	          showError();
554	        }
555	      };
556	
557	      const handleWishlistItem = async () => {
558	        if (!updateWishlist && !addToWishlist) return null;
559	        if (updateWishlist) {
560	          updateWishlist(product, variant, quantity);
561	          return;
562	        }
563	        // Guarded above, exactly as `addToCart` is in handleCartItem.
564	        addToWishlist!(product, variant, quantity);
565	      };
566	
567	      // child product of bundles do not have add to cart button
568	      if ((addToCart || updateCart) && !isProductPartOfBundle) {
569	        buttons.push(
570	          <Button
571	            key="cart-button"
572	            onClick={handleCartItem}
573	            isDisabled={disableButton}
574	            isLoading={isBasketLoading}
575	            width="100%"
576	            variant="solid"
577	            marginBottom={4}
578	          >
579	            {updateCart
580	              ? buttonText.update
581	              : isProductASet
582	              ? buttonText.addSetToCart
583	              : isProductABundle
584	              ? buttonText.addBundleToCart
585	              : buttonText.addToCart}
586	          </Button>,
587	        );
588	      }
589	
590	      // child product of bundles do not have add to wishlist button
591	      if ((addToWishlist || updateWishlist) && !isProductPartOfBundle) {
592	        buttons.push(
593	          <ButtonWithRegistration
594	            key="wishlist-button"
595	            onClick={handleWishlistItem}
596	            disabled={isWishlistLoading || !canAddToWishlist}
597	            isLoading={isWishlistLoading}
598	            width="100%"
599	            variant="outline"
600	            marginBottom={4}
601	          >
602	            {updateWishlist
603	              ? buttonText.update
604	              : isProductASet
605	              ? buttonText.addSetToWishlist
606	              : isProductABundle
607	              ? buttonText.addBundleToWishlist
608	              : buttonText.addToWishlist}
609	          </ButtonWithRegistration>,
610	        );
611	      }
612	
613	      if (showExpressOnPDP && !isProductASet && !isProductPartOfBundle && activeCurrency && priceData.currentPrice) {
614	        buttons.push(
615	          <SFPaymentsExpressButtons
616	            key="express-buttons"
617	            usage={EXPRESS_BUY_NOW}
618	            paymentCurrency={activeCurrency}
619	            paymentCountryCode={null}
620	            initialAmount={priceData.currentPrice}
621	            prepareBasket={prepareBasket}
622	            expressButtonLayout="vertical"
623	            maximumButtonCount={1}
624	          />,
625	        );
626	      }
627	
628	      // Add custom buttons if provided
629	      if (customButtons && customButtons.length > 0) {
630	        customButtons.forEach((customButton, index) => {
631	          buttons.push(
632	            React.cloneElement(customButton, {
633	              key: `custom-button-${index}`,
634	              width: customButton.props.width || '100%',
635	              marginBottom: customButton.props.marginBottom || 4,
636	            }),
637	          );
638	        });
639	      }
640	
641	      return buttons;
642	    };
643	
644	    // Bind the reference with our `scope` that includes the internal validate function for this component.
645	    // Other values can be added to this scope as required.
646	    if (typeof ref === 'function') {
647	      ref = ref.bind({ validateOrderability: validateAndShowError });
648	    }
649	
650	    // Set the quantity of bundle child in a product bundle to ensure availability messages appear
651	    if (isProductPartOfBundle && quantity != selectedBundleParentQuantity * childOfBundleQuantity) {
652	      setQuantity(selectedBundleParentQuantity * childOfBundleQuantity);
653	    }
654	
655	    useEffect(() => {
656	      if (isAddToCartModalOpen) {
657	        onAddToCartModalClose();
658	      }
659	    }, [location.pathname]);
660	
661	    useEffect(() => {
662	      if (!isProductASet && !isProductABundle && validateOrderability(variant, product, quantity, stockLevel)) {
663	        toggleShowOptionsMessage(false);
664	      }
665	    }, [variationParams]);
666	
667	    useEffect(() => {
668	      if (variant) {
669	        onVariantSelected(product, variant, quantity);
670	      }
671	    }, [variant?.productId, quantity]);
672	
673	    useEffect(() => {
674	      if ((isProductPartOfBundle || isProductPartOfSet) && product && product.type?.item) {
675	        onVariantSelected(product, null, childOfBundleQuantity || quantity);
676	      }
677	    }, [product, childOfBundleQuantity, quantity, isProductPartOfBundle, isProductPartOfSet]);
678	
679	    useEffect(() => {
680	      if (isProductPartOfBundle || isProductPartOfSet) {
681	        const key = product.itemId ?? product.id;
682	        // when showInventoryMessage is true, it means child product is not orderable
683	        // Deviation from the base file: optional call. The prop has no default, and the base
684	        // calls it unguarded — only reachable for set/bundle children, whose parent always
685	        // supplies it.
686	        setChildProductOrderability?.((previousState) => ({
687	          ...previousState,
688	          [key]: {
689	            showInventoryMessage,
690	            isOutOfStock,
691	            unfulfillable,
692	            stockLevel,
693	            productName: product?.name,
694	          },
695	        }));
696	      }
697	    }, [showInventoryMessage, inventoryMessage]);
698	
699	    // Auto-switch off pickup in store when product becomes unavailable at selected store
700	    useEffect(() => {
701	      setPickupEnabled(!!selectedStore?.inventoryId);
702	      if (pickupInStore && isSelectedStoreOutOfStock) {
703	        setPickupInStore(false);
704	      }
705	    }, [selectedStore]);
706	
707	    const handleDeliveryOptionChange = (value: string) => {
708	      setPickupInStore(value === DELIVERY_OPTIONS.PICKUP);
709	    };
710	
711	    return (
712	      <Flex direction={'column'} data-testid="product-view" ref={ref}>
713	        {/* Basic information etc. title, price, breadcrumb*/}
714	        <Box display={['block', 'block', 'block', 'none']}>
715	          {renderHeader({
716	            name: product?.name,
717	            product,
718	            priceData,
719	            currency: product?.currency || activeCurrency,
720	            category,
721	            isProductPartOfBundle,
722	          })}
723	        </Box>
724	        <Flex direction={['column', 'column', 'column', 'row']}>
725	          {showImageGallery && (
726	            <Box flex={1} mr={[0, 0, 0, 6, 6]}>
727	              {product ? (
728	                <>
729	                  <ImageGallery
730	                    size={imageSize}
731	                    imageGroups={product.imageGroups}
732	                    selectedVariationAttributes={variationParams}
733	                    lazy={isProductPartOfSet || isProductPartOfBundle}
734	                  />
735	                  <HideOnMobile>
736	                    {showFullLink && product && (
737	                      <Link to={`/product/${product.master.masterId}`} color="blue.600">
738	                        <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
739	                      </Link>
740	                    )}
741	                  </HideOnMobile>
742	                </>
743	              ) : (
744	                <ImageGallerySkeleton />
745	              )}
746	              {/* Custom footer content (e.g., Back to Selection button) */}
747	              {imageGalleryFooter && (
748	                <Box mt={6} mb={2}>
749	                  {imageGalleryFooter}
750	                </Box>
751	              )}
752	            </Box>
753	          )}
754	
755	          {/* Variations & Quantity Selector & CTA buttons */}
756	          {/* audit-allow: verbatim from base product-view (index.jsx:636-638); copy-first requires it unchanged */}
757	          <VStack
758	            align="stretch"
759	            spacing={8}
760	            flex={1}
761	            pb={[
762	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
763	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
764	              isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
765	              4,
766	            ]}
767	          >
768	            <Box display={['none', 'none', 'none', 'block']}>
769	              {renderHeader({
770	                name: product?.name,
771	                product,
772	                priceData,
773	                currency: product?.currency || activeCurrency,
774	                category,
775	                isProductPartOfBundle,
776	              })}
777	            </Box>
778	            <VStack align="stretch" spacing={4}>
779	              {isProductPartOfBundle && (
780	                <Box>
781	                  <Text fontWeight="medium" fontSize="md" aria-label="price">
782	                    <label>
783	                      {intl.formatMessage({
784	                        defaultMessage: 'Quantity',
785	                        id: 'product_view.label.quantity',
786	                      })}
787	                      : {childOfBundleQuantity}
788	                    </label>
789	                  </Text>
790	                </Box>
791	              )}
792	              {/*
793	                                Customize the skeletons shown for attributes to suit your needs. At the point
794	                                that we show the skeleton we do not know how many variations are selectable. So choose
795	                                a a skeleton that will meet most of your needs.
796	                            */}
797	              {showLoading ? (
798	                <>
799	                  {/* First Attribute Skeleton */}
800	                  <Skeleton height={6} width={32} />
801	                  <Skeleton height={20} width={64} />
802	
803	                  {/* Second Attribute Skeleton */}
804	                  <Skeleton height={6} width={32} />
805	                  <Skeleton height={20} width={64} />
806	                </>
807	              ) : (
808	                variationAttributes.map((attr: SfccVariationAttribute) => {
809	                  const { id, name, selectedValue, values } = attr;
810	
811	                  // renderVariationAttribute lets callers (e.g. the PDP) override how a specific
812	                  // variation attribute is displayed — the PDP injects ZimmColourSwatchGroup here.
813	                  // Returning undefined (not null) falls through to the base SwatchGroup below.
814	                  const custom = renderVariationAttribute?.(attr);
815	                  if (custom !== undefined) return <React.Fragment key={id}>{custom}</React.Fragment>;
816	
817	                  const swatches = values.map(
818	                    ({ href, name, image, value, orderable }: SfccVariationValue, index: number) => {
819	                      // audit-allow: verbatim from base product-view (index.jsx:689); copy-first requires it unchanged
820	                      const content = image ? (
821	                        <Box
822	                          height="100%"
823	                          width="100%"
824	                          minWidth="32px"
825	                          backgroundRepeat="no-repeat"
826	                          backgroundSize="cover"
827	                          backgroundColor={name.toLowerCase()}
828	                          backgroundImage={`url(${image.disBaseLink || image.link})`}
829	                        />
830	                      ) : (
831	                        name
832	                      );
833	                      const hasSelection = Boolean(selectedValue?.value);
834	                      const isSelected = selectedValue?.value === value;
835	                      const isFirst = index === 0;
836	                      // To mimic the behavior of a native radio input, only
837	                      // one swatch should receive tab focus; the rest can be
838	                      // selected using arrow keys when the swatch group has
839	                      // focus. The focused element is the selected option or
840	                      // the first in the group, if no option is selected.
841	                      // This is a slight difference, for simplicity, from the
842	                      // native element, where the first element is focused on
843	                      // `Tab` and the _last_ element is focused on `Shift+Tab`
844	                      const isFocusable = isSelected || (!hasSelection && isFirst);
845	                      return (
846	                        <Swatch
847	                          key={value}
848	                          href={href}
849	                          disabled={!orderable}
850	                          value={value}
851	                          name={name}
852	                          variant={id === 'color' ? 'circle' : 'square'}
853	                          selected={isSelected}
854	                          isFocusable={isFocusable}
855	                        >
856	                          {content}
857	                        </Swatch>
858	                      );
859	                    },
860	                  );
861	                  return (
862	                    <SwatchGroup
863	                      key={id}
864	                      value={selectedValue?.value}
865	                      displayName={selectedValue?.name || ''}
866	                      label={intl.formatMessage(
867	                        {
868	                          defaultMessage: '{variantType}',
869	                          id: 'product_view.label.variant_type',
870	                        },
871	                        { variantType: name },
872	                      )}
873	                      handleChange={onVariationChange ? (value: string) => onVariationChange(id, value) : undefined}
874	                    >
875	                      {swatches}
876	                    </SwatchGroup>
877	                  );
878	                })
879	              )}
880	
881	              {/* audit-allow: verbatim from base product-view (index.jsx:754); copy-first requires it unchanged */}
882	              {!isProductASet && !isProductPartOfBundle && (
883	                <VStack align="stretch" maxWidth={'200px'}>
884	                  <Box fontWeight="bold">
885	                    <label htmlFor="quantity">
886	                      {intl.formatMessage({
887	                        defaultMessage: 'Quantity',
888	                        id: 'product_view.label.quantity',
889	                      })}:
890	                    </label>
891	                  </Box>
892	
893	                  <QuantityPicker
894	                    id="quantity"
895	                    step={stepQuantity}
896	                    value={quantity}
897	                    min={minOrderQuantity}
898	                    {...(maxOrderQuantity != null && { max: maxOrderQuantity })}
899	                    onChange={(stringValue: string, numberValue: number) => {
900	                      // Set the Quantity of product to value of input if value number
901	                      if (numberValue >= 0) {
902	                        setQuantity(numberValue);
903	                        if (isProductABundle) setSelectedBundleQuantity(numberValue);
904	                      } else if (stringValue === '') {
905	                        // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
906	                        // User will not be able to add '' qauntity to the cart due to the add to cart button enablement rules
907	                        setQuantity(stringValue);
908	                      }
909	                    }}
910	                    onBlur={(e: React.FocusEvent<HTMLInputElement>) => {
911	                      // Default to 1the `minOrderQuantity` if a user leaves the box with an invalid value
912	                      const value = e.target.value;
913	                      if (parseInt(value) < 0 || value === '') {
914	                        setQuantity(minOrderQuantity);
915	                        if (isProductABundle) setSelectedBundleQuantity(minOrderQuantity);
916	                      }
917	                    }}
918	                    onFocus={(e: React.FocusEvent<HTMLInputElement>) => {
919	                      // This is useful for mobile devices, this allows the user to pop open the keyboard and set the
920	                      // new quantity with one click. NOTE: This is something that can be refactored into the parent
921	                      // component, potentially as a prop called `selectInputOnFocus`.
922	                      e.target.select();
923	                    }}
924	                    productName={product?.name}
925	                  />
926	                </VStack>
927	              )}
928	              <Box ref={errorContainerRef}>
929	                {!showLoading && showOptionsMessage && (
930	                  <Fade in={true}>
931	                    <Text color="orange.600" fontWeight={600} marginBottom={8}>
932	                      {intl.formatMessage({
933	                        defaultMessage: 'Please select all your options above',
934	                      })}
935	                    </Text>
936	                  </Fade>
937	                )}
938	              </Box>
939	              <HideOnDesktop>
940	                {showFullLink && product && (
941	                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
942	                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
943	                  </Link>
944	                )}
945	              </HideOnDesktop>
946	              {isProductASet && <p>{product?.shortDescription}</p>}
947	            </VStack>
948	
949	            <Box>
950	              {!showLoading && showInventoryMessage && !customInventoryMessage && (
951	                <Fade in={true}>
952	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
953	                    {inventoryMessage}
954	                  </Text>
955	                </Fade>
956	              )}
957	              {!showLoading && customInventoryMessage && (
958	                <Fade in={true}>
959	                  <Text color="orange.600" fontWeight={600} marginBottom={8}>
960	                    {customInventoryMessage}
961	                  </Text>
962	                </Fade>
963	              )}
964	              <Box>
965	                {showDeliveryOptions && (
966	                  <>
967	                    <Box mb={4}>
968	                      <Text fontWeight={600} mb={3}>
969	                        <FormattedMessage defaultMessage="Delivery:" id="product_view.label.delivery" />
970	                      </Text>
971	                      <RadioGroup
972	                        value={pickupInStore ? DELIVERY_OPTIONS.PICKUP : DELIVERY_OPTIONS.DELIVERY}
973	                        onChange={handleDeliveryOptionChange}
974	                        mb={1}
975	                      >
976	                        <Stack direction="column" spacing={2}>
977	                          <Radio value={DELIVERY_OPTIONS.DELIVERY} isDisabled={disableButton}>
978	                            <FormattedMessage
979	                              defaultMessage="Ship to Address"
980	                              id="product_view.label.ship_to_address"
981	                            />
982	                          </Radio>
983	                          {storeLocatorEnabled && (
984	                            <Radio
985	                              value={DELIVERY_OPTIONS.PICKUP}
986	                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
987	                            >
988	                              <FormattedMessage
989	                                defaultMessage="Pick Up in Store"
990	                                id="product_view.label.pickup_in_store"
991	                              />
992	                            </Radio>
993	                          )}
994	                        </Stack>
995	                      </RadioGroup>
996	                    </Box>
997	
998	                    {storeLocatorEnabled && (
999	                      <>
1000	                        {storeName && inventoryId && (
1001	                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
1002	                            {!isSelectedStoreOutOfStock
1003	                              ? intl.formatMessage(
1004	                                  {
1005	                                    id: 'product_view.status.in_stock_at_store',
1006	                                    defaultMessage: 'In stock at {storeName}',
1007	                                  },
1008	                                  {
1009	                                    storeName: (
1010	                                      <Link
1011	                                        as="button"
1012	                                        color="blue.600"
1013	                                        textDecoration="underline"
1014	                                        onClick={onOpenStoreLocator}
1015	                                      >
1016	                                        {storeName}
1017	                                      </Link>
1018	                                    ),
1019	                                  },
1020	                                )
1021	                              : intl.formatMessage(
1022	                                  {
1023	                                    id: 'product_view.status.out_of_stock_at_store',
1024	                                    defaultMessage: 'Out of Stock at {storeName}',
1025	                                  },
1026	                                  {
1027	                                    storeName: (
1028	                                      <Link
1029	                                        as="button"
1030	                                        color="blue.600"
1031	                                        textDecoration="underline"
1032	                                        onClick={onOpenStoreLocator}
1033	                                      >
1034	                                        {storeName}
1035	                                      </Link>
1036	                                    ),
1037	                                  },
1038	                                )}
1039	                          </Text>
1040	                        )}
1041	
1042	                        {/* Show label if pickup is disabled due to no store/inventoryId */}
1043	                        {!pickupEnabled && !storeName && !inventoryId && (
1044	                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
1045	                            <FormattedMessage
1046	                              defaultMessage="Pick up in "
1047	                              id="product_view.label.pickup_in_select_store_prefix"
1048	                            />{' '}
1049	                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
1050	                              <FormattedMessage
1051	                                defaultMessage="Select Store"
1052	                                id="product_view.label.select_store_link"
1053	                              />
1054	                            </Link>
1055	                          </Text>
1056	                        )}
1057	                      </>
1058	                    )}
1059	                  </>
1060	                )}
1061	                <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
1062	                  {renderActionButtons()}
1063	                </Box>
1064	                {footerLinks}
1065	              </Box>
1066	            </Box>
1067	          </VStack>
1068	        </Flex>
1069	
1070	        {/* Sticky call-to-action buttons for mobile and certain product types */}
1071	        <Box
1072	          position="fixed"
1073	          bg="white"
1074	          width="100%"
1075	          display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
1076	          p={[4, 4, 6]}
1077	          left={0}
1078	          bottom={0}
1079	          zIndex={2}
1080	          boxShadow={theme.shadows.top}
1081	        >
1082	          {renderActionButtons()}
1083	        </Box>
1084	
1085	        {/* Loading overlay during express payment confirmation */}
1086	        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
1087	      </Flex>
1088	    );
1089	  },
1090	);
1091	
1092	ProductView.displayName = 'ProductView';
1093	
1094	/*
1095	 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
1096	 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
1097	 * same prop contract, and do so at compile time for every caller rather than as a dev-only
1098	 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
1099	 */
1100	
1101	export default ProductView;
